target.sourceText:
args.reduce((prev, current) => {
    Object.entries(current)
      .map(([currency, val]) => ({currency, val}))
      .forEach(prop => {
        prev[prop.currency] = (prev[prop.currency] || 0) + prop.val
      })
    return prev
  }, {})

